+/// Temporary observation-only recognition counters; not a production API.
+#[allow(missing_docs)]
+pub mod recognition_diagnostic {
+    use std::cell::{Cell, RefCell};
+    use std::collections::BTreeMap;
+    std::thread_local! {
+        static ENABLED: Cell<bool> = const { Cell::new(false) };
+        static COUNTS: RefCell<BTreeMap<String, u64>> = const { RefCell::new(BTreeMap::new()) };
+        static NOTES: RefCell<Vec<String>> = const { RefCell::new(Vec::new()) };
+    }
+    pub fn configure(enabled: bool) {
+        ENABLED.with(|v| v.set(enabled));
+        if enabled { COUNTS.with(|v| v.borrow_mut().clear()); NOTES.with(|v| v.borrow_mut().clear()); }
+    }
+    pub fn add(name: &str, amount: u64) {
+        if ENABLED.with(Cell::get) {
+            COUNTS.with(|v| { let mut v = v.borrow_mut(); *v.entry(name.to_owned()).or_default() += amount; });
+        }
+    }
+    pub fn note(value: String) {
+        if ENABLED.with(Cell::get) { NOTES.with(|v| v.borrow_mut().push(value)); }
+    }
+    pub fn counts() -> BTreeMap<String, u64> { COUNTS.with(|v| v.borrow().clone()) }
+    pub fn notes() -> Vec<String> { NOTES.with(|v| v.borrow().clone()) }
+}
